//! Armrest spline featurization parity (ephemeris-ktg.9).
//!
//! Fixtures under `tests/fixtures/htr-armrest-parity/` were generated by
//! `scripts/gen_htr_armrest_parity_fixtures.py` (pure-Python mirror of the
//! ported armrest pipeline). Assert Rust matches expected tensors to ~1e-4.

use ephemeris_core::stroke_htr::armrest::{featurize_armrest_ink, featurize_line_armrest};

use std::path::PathBuf;

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/htr-armrest-parity")
}

#[derive(serde::Deserialize)]
struct Expected {
    features: Vec<[f32; 4]>,
}

fn load_case(name: &str) -> (String, Vec<[f32; 4]>) {
    let dir = fixture_dir();
    let ink = std::fs::read_to_string(dir.join(format!("{name}.ink.txt")))
        .expect("ink fixture")
        .trim()
        .to_string();
    let expected: Expected = serde_json::from_str(
        &std::fs::read_to_string(dir.join(format!("{name}.expected_features.json")))
            .expect("features json"),
    )
    .expect("parse features");
    (ink, expected.features)
}

fn assert_features_close(got: &[[f32; 4]], expected: &[[f32; 4]]) {
    assert_eq!(
        got.len(),
        expected.len(),
        "timestep count: got {} expected {}",
        got.len(),
        expected.len()
    );
    for (i, (g, e)) in got.iter().zip(expected.iter()).enumerate() {
        for c in 0..4 {
            let diff = (g[c] - e[c]).abs();
            assert!(
                diff < 1e-4,
                "t={i} c={c}: got {} expected {} (Δ={diff})",
                g[c],
                e[c]
            );
        }
    }
}

#[test]
fn armrest_parity_synth_two_stroke() {
    let (ink, expected) = load_case("synth-two-stroke");
    let got = featurize_armrest_ink(&ink);
    assert_features_close(&got, &expected);
}

#[test]
fn armrest_parity_jabberwocky_and() {
    let (ink, expected) = load_case("jabberwocky-and");
    let got = featurize_armrest_ink(&ink);
    assert_features_close(&got, &expected);
}

#[test]
fn armrest_stroke_line_matches_ink_literal() {
    let (ink, expected) = load_case("synth-two-stroke");
    let line = ephemeris_core::stroke_htr::armrest::stroke_line_from_armrest_ink(&ink);
    let got = featurize_line_armrest(&line);
    assert_features_close(&got, &expected);
}

/// Optional end-to-end decode when an armrest model is installed.
///
/// Run with:
/// `EPHEMERIS_ARMREST_MODEL_DIR=... cargo test -p ephemeris-core --features htr -- --ignored`
#[test]
#[ignore]
fn armrest_model_decodes_when_present() {
    let dir = std::env::var("EPHEMERIS_ARMREST_MODEL_DIR")
        .or_else(|_| std::env::var("EPHEMERIS_HTR_MODEL_DIR"))
        .ok()
        .map(PathBuf::from)
        .filter(|p| p.join("model.onnx").is_file() || p.join("model.rten").is_file());
    let Some(dir) = dir else {
        eprintln!("skip: no armrest model dir");
        return;
    };
    let meta = std::fs::read_to_string(dir.join("meta.json")).unwrap_or_default();
    assert!(
        meta.contains("armrest_spline") || dir.join("charset.txt").is_file(),
        "expected armrest meta/charset in {}",
        dir.display()
    );
    let (ink, _) = load_case("synth-two-stroke");
    let line = ephemeris_core::stroke_htr::armrest::stroke_line_from_armrest_ink(&ink);
    let tx = ephemeris_core::transcriber::StrokeHtrTranscriber::from_parts(true, Some(dir));
    let spans = ephemeris_core::transcriber::Transcriber::transcribe(&tx, &line.strokes)
        .expect("transcribe");
    // Model may or may not recognise the synthetic scribble; just ensure it runs.
    let _ = spans;
}
